const locs = await sdk.scanNearbyLocs(80);
const uniq = {};
for (const l of locs) uniq[l.name] = (uniq[l.name]||0)+1;
const p = sdk.getState().player;
const interesting = locs.filter(l=>/oak|willow|maple|yew|magic|teak|tree/i.test(l.name) && !/stump|dead|hollow/i.test(l.name));
// group by name, show nearest few
const byName = {};
for (const t of interesting) { (byName[t.name]=byName[t.name]||[]).push(t); }
const out = {};
for (const [n,arr] of Object.entries(byName)) { arr.sort((a,b)=>a.distance-b.distance); out[n] = {count:arr.length, nearest: arr.slice(0,5).map(t=>({x:t.x,z:t.z,d:t.distance}))}; }
return {player:{x:p.worldX,z:p.worldZ}, out};

