function oreCount(){ return sdk.countInventoryItems(/ore/i); }
async function mineType(type, target){
  const re = new RegExp(type,'i');
  let mined=0, fails=0;
  while (sdk.countInventoryItems(re) < target && fails < 15){
    const rocks = await sdk.scanNearbyLocs(14);
    const rock = rocks.filter(l=>re.test(l.name) && l.optionsWithIndex.some(o=>/^mine$/i.test(o.text))).sort((a,b)=>a.distance-b.distance)[0];
    if(!rock){ fails++; await sdk.waitForTicks(2); continue; }
    const before = sdk.countInventoryItems(re);
    await sdk.sendInteractLoc(rock.x, rock.z, rock.id, 1);
    const ok = await sdk.waitForCondition(s=>s.inventory.reduce((a,i)=>re.test(i.name)?a+i.count:a,0) > before, 4000).then(()=>true).catch(()=>false);
    if(ok) mined++; else fails++;
  }
  return mined;
}
